// Turns every point after `pivot` round it by `q`.
void turnAfter(std::vector<glm::vec3>& p, size_t pivot, const glm::quat& q) {
    for (size_t j = pivot + 1; j < p.size(); ++j) p[j] = p[pivot] + q * (p[j] - p[pivot]);
}
